\set ON_ERROR_STOP on
-- This is an isolated local database. These helpers are never installed in production.
create schema test;
create table test.results (label text primary key);
create table test.context (key text primary key, value text not null);
grant usage on schema test to anon, authenticated;
grant insert on test.results to anon, authenticated;
grant select, insert, update on test.context to authenticated;
grant select on test.context to anon;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$ begin
  if condition is distinct from true then raise exception 'FAILED: %',label; end if;
  insert into test.results values(label);
end; $$;
create function test.denied(statement text,expected_state text,label text) returns void language plpgsql as $$
declare received_state text; begin
  begin execute statement; exception when others then get stacked diagnostics received_state = returned_sqlstate; end;
  if received_state is distinct from expected_state then raise exception 'FAILED: %; expected SQLSTATE %, received %',label,expected_state,coalesce(received_state,'success'); end if;
  insert into test.results values(label);
end; $$;
create function test.value(p_key text) returns text language sql stable as $$ select value from test.context where key = p_key; $$;
create function test.lead(p_id text) returns jsonb language sql immutable as $$ select jsonb_build_object(
  'id',p_id,'name','Teste local','company','Empresa teste','email','lead@example.test','phone','','source','Indicação',
  'createdAt','2026-10-07T12:00:00.000Z','callDate','','objection','','closedAt','','lastContactAt','2026-10-07T12:00:00.000Z',
  'notes','','pain','','closerError','','callSummary','','status','Lead novo','attendance','Pendente','urgency','Média',
  'financialCapacity','Não avaliada','decisionMaker',false,'ticket',10000,'closedValue',0,'callScore',null); $$;

