insert into test.context values('expiry',public.create_workspace('Expiry test')::text);
insert into test.context values('unconfirmed_token',(public.invite_member(test.value('expiry')::uuid,'person8@example.test','admin')->>'token'));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',false);
select test.denied(format('select public.accept_invitation(%L)',test.value('unconfirmed_token')),'42501','unconfirmed email cannot accept valid invitation');
reset role;
update public.invitations set expires_at=now()-interval '1 hour',created_at=now()-interval '8 days' where workspace_id=test.value('expiry')::uuid;
set role anon;
select test.ok(public.list_invitation_preview(test.value('unconfirmed_token')) is null,'expired invitation is hidden from token preview');
reset role;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',false);
select test.denied(format('select public.accept_invitation(%L)',test.value('unconfirmed_token')),'42501','expired invitation cannot be accepted');
reset role;
select 'SQL assertions passed: ' || count(*) from test.results;
-- Set up an invitation for simultaneous callbacks, plus administrators for concurrent revocation.
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
insert into test.context values('accept_race',public.create_workspace('Acceptance race')::text);
insert into test.context values('accept_race_token',public.invite_member(test.value('accept_race')::uuid,'person6@example.test','admin')->>'token');
insert into test.context values('admin_race',public.create_workspace('Administration race')::text);
select public.admin_update_subscription(test.value('admin_race')::uuid,'team','active',3);
insert into test.context values('admin_race_owner_token',public.invite_member(test.value('admin_race')::uuid,'person6@example.test','admin')->>'token');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',false);
select public.accept_invitation(test.value('admin_race_owner_token'));
insert into test.context values('admin_race_a_token',public.invite_member(test.value('admin_race')::uuid,'person9@example.test','admin')->>'token');
insert into test.context values('admin_race_b_token',public.invite_member(test.value('admin_race')::uuid,'person10@example.test','admin')->>'token');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000009',false);
select public.accept_invitation(test.value('admin_race_a_token'));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000010',false);
select public.accept_invitation(test.value('admin_race_b_token'));
reset role;
